  if (condition == TRUE) {

    cat("::: {.callout-warning}\n")
    cat("Fewer than 7 days were available last week from the ECCC data source. The weekly mean temperature and anomaly are likely incorrect.\n")
    cat(":::\n")


  } else {
    cat('')
  }

}

